"use client";

import { cn } from "@/lib/utils";
import { Menu, X } from "lucide-react";
import React, { useEffect, useState } from "react";
import { SidebarContext, useSidebar } from "./sidebar-context";
import { Tooltip, TooltipContent, TooltipTrigger } from "./TooltipBlock";

// ==========================================
// 1. PROVIDER & ROOT LAYOUT
// ==========================================
export interface SidebarProviderProps {
  children: React.ReactNode;
  defaultExpanded?: boolean;
  color?: string;
  className?: string;
}

export function SidebarProvider({
  children,
  defaultExpanded = true,
  color = "primary",
  className,
}: SidebarProviderProps) {
  const [expanded, setExpanded] = useState(defaultExpanded);
  const [isMobileOpen, setIsMobileOpen] = useState(false);

  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth >= 768) setIsMobileOpen(false);
    };
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  return (
    <SidebarContext.Provider
      value={{ expanded, setExpanded, isMobileOpen, setIsMobileOpen, color }}
    >
      <div
        className={cn(
          "relative flex h-full min-h-screen w-full overflow-hidden bg-muted",
          className,
        )}
      >
        {children}
      </div>
    </SidebarContext.Provider>
  );
}

// ==========================================
// 2. MAIN SIDEBAR CONTAINER
// ==========================================
export interface SidebarProps extends React.HTMLAttributes<HTMLElement> {
  variant?: "attached" | "floating";
}

export function Sidebar({
  variant = "attached",
  className,
  children,
  ...props
}: SidebarProps) {
  const { expanded, isMobileOpen, setIsMobileOpen } = useSidebar();

  return (
    <>
      {/* Backdrop stays mounted so it can fade both in and out with the drawer */}
      <div
        aria-hidden={!isMobileOpen}
        onClick={() => setIsMobileOpen(false)}
        className={cn(
          "fixed inset-0 z-40 bg-black/50 backdrop-blur-sm md:hidden",
          "transition-[opacity,visibility] duration-500 ease-[cubic-bezier(0.32,0.72,0,1)] motion-reduce:transition-none",
          isMobileOpen ? "visible opacity-100" : "invisible opacity-0",
        )}
      />

      <aside
        className={cn(
          "fixed inset-y-0 left-0 z-50 flex flex-col md:relative md:translate-x-0",
          // Mobile drawer glides in on a decelerating curve; desktop rail keeps the shorter width tween
          "transition-[width,transform] duration-500 ease-[cubic-bezier(0.32,0.72,0,1)] will-change-transform motion-reduce:transition-none md:duration-300 md:ease-in-out",
          expanded ? "w-64" : "w-16",
          isMobileOpen ? "translate-x-0" : "-translate-x-full",
          variant === "attached"
            ? "border-r border-border bg-card text-card-foreground"
            : "m-4 h-[calc(100vh-2rem)] rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
          // Lifted off the backdrop while it is an open drawer (mobile only state)
          isMobileOpen && "shadow-2xl",
          className,
        )}
        {...props}
      >
        {children}
      </aside>
    </>
  );
}

// ==========================================
// 3. HEADER, FOOTER, BRAND
// ==========================================
export function SidebarHeader({
  className,
  children,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  const { expanded, setIsMobileOpen } = useSidebar();

  return (
    <div
      className={cn(
        "flex h-16 shrink-0 items-center justify-between transition-all",
        expanded ? "px-4" : "justify-center px-0",
        className,
      )}
      {...props}
    >
      {children}
      <button
        onClick={() => setIsMobileOpen(false)}
        className="md:hidden p-1 text-muted-foreground hover:bg-muted rounded-md"
      >
        <X className="w-5 h-5" />
      </button>
    </div>
  );
}

export function SidebarBrand({
  icon,
  className,
  children,
  ...props
}: React.HTMLAttributes<HTMLDivElement> & { icon?: React.ReactNode }) {
  const { expanded } = useSidebar();

  return (
    <div
      className={cn(
        "flex items-center font-bold text-xl text-foreground",
        className,
      )}
      {...props}
    >
      {icon && <div className="shrink-0">{icon}</div>}
      <div
        className={cn(
          "whitespace-nowrap overflow-hidden transition-all duration-300",
          expanded
            ? "max-w-[200px] opacity-100 ml-2"
            : "max-w-0 opacity-0 ml-0",
        )}
      >
        {children}
      </div>
    </div>
  );
}

export function SidebarFooter({
  className,
  children,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      className={cn(
        "mt-auto flex shrink-0 flex-col border-t border-border p-3",
        className,
      )}
      {...props}
    >
      {children}
    </div>
  );
}

export function SidebarContent({
  className,
  children,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      className={cn(
        "flex-1 overflow-y-auto overflow-x-hidden p-3 space-y-4 [scrollbar-width:none] [-ms-overflow-style:none] [&::-webkit-scrollbar]:hidden",
        className,
      )}
      {...props}
    >
      {children}
    </div>
  );
}

// ==========================================
// 4. GROUPS & ITEMS
// ==========================================
export function SidebarGroup({
  label,
  className,
  children,
  ...props
}: React.HTMLAttributes<HTMLDivElement> & { label?: string }) {
  const { expanded } = useSidebar();

  return (
    <div className={cn("flex flex-col gap-1", className)} {...props}>
      {label && (
        <div
          className={cn(
            "px-3 text-xs font-semibold uppercase tracking-wider text-muted-foreground transition-all duration-300 overflow-hidden",
            expanded
              ? "max-h-[20px] opacity-100 mb-1"
              : "max-h-0 opacity-0 mb-0",
          )}
        >
          {label}
        </div>
      )}
      {children}
    </div>
  );
}

export interface SidebarItemProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  icon?: React.ReactNode;
  active?: boolean;
}

export function SidebarItem({
  icon,
  active,
  className,
  children,
  ...props
}: SidebarItemProps) {
  const { expanded, color } = useSidebar();

  const item = (
    <button
      className={cn(
        "group relative flex w-full items-center rounded-lg px-3 py-2 text-sm font-medium transition-all duration-200 outline-none",
        !expanded && "justify-center px-0",
        active
          ? color === "primary" || color === "default" || !color
            ? "bg-primary/10 text-primary font-medium"
            : `bg-${color}-50 text-${color}-600 dark:bg-${color}-500/10 dark:text-${color}-400`
          : "text-muted-foreground hover:bg-muted hover:text-foreground",
        className,
      )}
      {...props}
    >
      {/* Icon Slot */}
      {icon && (
        <div
          className={cn(
            "shrink-0 transition-transform duration-200",
            active && "scale-110",
          )}
        >
          {icon}
        </div>
      )}

      {/* Label Slot (Uses max-w to force strict collapsing) */}
      <div
        className={cn(
          "whitespace-nowrap overflow-hidden transition-all duration-300 text-left",
          expanded
            ? "max-w-[200px] opacity-100 ml-3"
            : "max-w-0 opacity-0 ml-0",
        )}
      >
        {children}
      </div>
    </button>
  );

  // Collapsed rail: the label moves into a Tooltip. It portals to the body,
  // so it is never clipped by the rail's overflow the way an absolutely
  // positioned label would be.
  if (expanded) return item;
  return (
    <Tooltip delayDuration={100}>
      {/* The button is the tab stop; the trigger wrapper only listens. */}
      <TooltipTrigger className="block w-full" tabIndex={-1}>
        {item}
      </TooltipTrigger>
      <TooltipContent side="right" sideOffset={12} className="font-semibold">
        {children}
      </TooltipContent>
    </Tooltip>
  );
}

// ==========================================
// 5. UTILITY TRIGGERS
// ==========================================
export function SidebarTrigger({
  className,
  ...props
}: React.ButtonHTMLAttributes<HTMLButtonElement>) {
  const { expanded, setExpanded } = useSidebar();

  return (
    <button
      onClick={() => setExpanded(!expanded)}
      className={cn(
        "hidden md:flex p-2 rounded-lg text-muted-foreground hover:bg-muted transition-colors",
        className,
      )}
      {...props}
    >
      <Menu className="w-5 h-5" />
    </button>
  );
}

export function MobileSidebarTrigger({
  className,
  ...props
}: React.ButtonHTMLAttributes<HTMLButtonElement>) {
  const { setIsMobileOpen } = useSidebar();

  return (
    <button
      onClick={() => setIsMobileOpen(true)}
      className={cn(
        "md:hidden p-2 rounded-lg text-muted-foreground hover:bg-muted transition-colors",
        className,
      )}
      {...props}
    >
      <Menu className="w-5 h-5" />
    </button>
  );
}

"use client";

import React, { createContext, useContext } from "react";

interface SidebarContextType {
  expanded: boolean;
  setExpanded: React.Dispatch<React.SetStateAction<boolean>>;
  isMobileOpen: boolean;
  setIsMobileOpen: React.Dispatch<React.SetStateAction<boolean>>;
  color: string;
}

export const SidebarContext = createContext<SidebarContextType | undefined>(undefined);

export function useSidebar() {
  const context = useContext(SidebarContext);
  if (!context)
    throw new Error(
      "Sidebar components must be rendered within a SidebarProvider",
    );
  return context;
}

"use client";

import { cn } from "@/lib/utils";
import React, {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { createPortal } from "react-dom";

/**
 * Positioning has to happen before the browser paints, or the tooltip shows up
 * at its placeholder coordinates for one frame and then jumps into place.
 * useLayoutEffect warns when it runs on the server, and TooltipContent renders
 * nothing until the trigger has committed, so falling back to useEffect there
 * costs nothing.
 */
const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? useLayoutEffect : useEffect;

// ==========================================
// 1. CONTEXT
// ==========================================
interface TooltipContextType {
  open: boolean;
  setOpen: React.Dispatch<React.SetStateAction<boolean>>;
  delayDuration: number;
  /**
   * The trigger node itself, held in state rather than a ref. A ref shared
   * through context makes every read of this context a ref read during render;
   * a plain node lets the content position and portal itself without one.
   */
  trigger: HTMLDivElement | null;
  setTrigger: React.Dispatch<React.SetStateAction<HTMLDivElement | null>>;
}
const TooltipContext = createContext<TooltipContextType | undefined>(undefined);

// ==========================================
// 2. PROVIDER (Optional: For wrapping the app)
// ==========================================
export function TooltipProvider({ children }: { children: React.ReactNode }) {
  return <>{children}</>;
}

// ==========================================
// 3. TOOLTIP ROOT (State Manager)
// ==========================================
export interface TooltipProps {
  children: React.ReactNode;
  delayDuration?: number;
}

export function Tooltip({ children, delayDuration = 200 }: TooltipProps) {
  const [open, setOpen] = useState(false);
  const [trigger, setTrigger] = useState<HTMLDivElement | null>(null);

  // The open/close delay is owned by the trigger, not shared through context:
  // a timeout ref captured by a context handler would make every read of this
  // context look like a ref read during render.
  const value = useMemo(
    () => ({ open, setOpen, delayDuration, trigger, setTrigger }),
    [open, delayDuration, trigger],
  );

  return (
    <TooltipContext.Provider value={value}>
      {children}
    </TooltipContext.Provider>
  );
}

// ==========================================
// 4. TRIGGER
// ==========================================
export interface TooltipTriggerProps
  extends React.HTMLAttributes<HTMLDivElement> {
  asChild?: boolean;
}

export function TooltipTrigger({
  children,
  className,
  ...props
}: TooltipTriggerProps) {
  const context = useContext(TooltipContext);
  if (!context) throw new Error("TooltipTrigger must be used within a Tooltip");

  const { open, setOpen, delayDuration, setTrigger } = context;
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const handleOpen = useCallback(() => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    timeoutRef.current = setTimeout(() => setOpen(true), delayDuration);
  }, [setOpen, delayDuration]);

  const handleClose = useCallback(() => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    setOpen(false);
  }, [setOpen]);

  useEffect(
    () => () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    },
    [],
  );

  return (
    <div
      ref={setTrigger}
      onMouseEnter={handleOpen}
      onMouseLeave={handleClose}
      onFocus={handleOpen}
      onBlur={handleClose}
      className={cn("inline-block", className)}
      tabIndex={0}
      aria-haspopup="dialog"
      aria-expanded={open}
      {...props}
    >
      {children}
    </div>
  );
}

// ==========================================
// 5. CONTENT (Portal Renderer)
// ==========================================
export interface TooltipContentProps
  extends React.HTMLAttributes<HTMLDivElement> {
  side?: "top" | "right" | "bottom" | "left";
  align?: "start" | "center" | "end";
  sideOffset?: number;
}

// The entrance grows out of the trigger's edge: a tooltip above the trigger
// scales from its own bottom edge and slides up a touch, and so on.
const ENTER_FROM_SIDE: Record<NonNullable<TooltipContentProps["side"]>, string> = {
  top: "origin-bottom slide-in-from-bottom-1",
  bottom: "origin-top slide-in-from-top-1",
  left: "origin-right slide-in-from-right-1",
  right: "origin-left slide-in-from-left-1",
};

export function TooltipContent({
  side = "top",
  align = "center",
  sideOffset = 6,
  className,
  children,
  ...props
}: TooltipContentProps) {
  const context = useContext(TooltipContext);
  if (!context) throw new Error("TooltipContent must be used within a Tooltip");

  const { open, trigger: triggerEl } = context;
  const [coords, setCoords] = useState({ top: -9999, left: -9999 });
  // Stale coordinates from the previous open would otherwise paint first.
  const [positioned, setPositioned] = useState(false);
  const contentRef = useRef<HTMLDivElement>(null);

  // Forget the measurement on close, so the next open cannot flash at last
  // time’s coordinates before the layout effect re-measures.
  const [wasOpen, setWasOpen] = useState(open);
  if (wasOpen !== open) {
    setWasOpen(open);
    if (!open) setPositioned(false);
  }

  useIsomorphicLayoutEffect(() => {
    if (!open || !triggerEl || !contentRef.current) return;

    // Resolve the document/window the trigger actually lives in, so the
    // tooltip works when rendered inside an iframe (e.g. docs device preview).
    const doc = triggerEl.ownerDocument;
    const win = doc.defaultView ?? window;

    const updatePosition = () => {
      const trigger = triggerEl.getBoundingClientRect();
      // offsetWidth/Height are the untransformed layout box; a bounding rect
      // would report the shrunken size while the zoom-in entrance runs.
      const content = {
        width: contentRef.current!.offsetWidth,
        height: contentRef.current!.offsetHeight,
      };
      let top = 0;
      let left = 0;

      // 1. Calculate Side
      if (side === "top") top = trigger.top - content.height - sideOffset;
      if (side === "bottom") top = trigger.bottom + sideOffset;
      if (side === "left") left = trigger.left - content.width - sideOffset;
      if (side === "right") left = trigger.right + sideOffset;

      // 2. Calculate Align
      if (side === "top" || side === "bottom") {
        if (align === "center")
          left = trigger.left + trigger.width / 2 - content.width / 2;
        if (align === "start") left = trigger.left;
        if (align === "end") left = trigger.right - content.width;
      } else {
        if (align === "center")
          top = trigger.top + trigger.height / 2 - content.height / 2;
        if (align === "start") top = trigger.top;
        if (align === "end") top = trigger.bottom - content.height;
      }

      setCoords({ top: top + win.scrollY, left: left + win.scrollX });
      setPositioned(true);
    };

    updatePosition();
    // Use capture phase for scroll to ensure it updates during nested scroll containers
    win.addEventListener("scroll", updatePosition, true);
    win.addEventListener("resize", updatePosition);
    return () => {
      win.removeEventListener("scroll", updatePosition, true);
      win.removeEventListener("resize", updatePosition);
    };
  }, [open, side, align, sideOffset, triggerEl]);

  // triggerEl is null until the trigger commits, which also covers SSR: there
  // is no document to portal into on the server.
  if (!triggerEl || !open) return null;

  // Portal into the trigger's own document (supports iframe rendering).
  const portalTarget = triggerEl.ownerDocument.body;

  return createPortal(
    <div
      ref={contentRef}
      role="tooltip"
      className={cn(
        "absolute z-[9999] px-3 py-1.5 text-xs font-medium text-primary-foreground bg-primary rounded-md shadow-md pointer-events-none",
        // `duration-150` sets transition-duration too, and the browser default
        // transition-property is `all` — without `transition-none` top/left
        // would tween from the placeholder coordinates, sliding the tooltip
        // across the screen instead of opening in place.
        "transition-none animate-in fade-in zoom-in-95 duration-150",
        ENTER_FROM_SIDE[side],
        className,
      )}
      style={{
        top: coords.top,
        left: coords.left,
        visibility: positioned ? "visible" : "hidden",
      }}
      {...props}
    >
      {children}
    </div>,
    portalTarget,
  );
}
